    q6327: { h: "eb7694144991", text: "The product accounts system halted when lightning struck: does connecting a generator appeal to you?" },
    q7228: { h: "ea78693eb383", text: "Putting what the AI has learned to work only after a human has tested it: does this approval by testing appeal to you?" },
    q7229: { h: "dae51b1a56d6", text: "Keeping a patient's hidden illness to yourself, not telling outside: would you keep this silence?" },
    q7230: { h: "a4eb80a57aed", text: "Looking to see whether anyone is in the field before flying an AI drone: would you accept this habit of looking?" },
    q7231: { h: "65449de9babc", text: "Never saving a customer's passcode in AI finance: will you keep this ban on saving?" },
    q7232: { h: "acd266ee9ff9", text: "A human eye must stay on the decisions of what the machine has learned: would you enjoy this rule of the eye?" },
    q7233: { h: "b2c120714c49", text: "Student data under the latch, never for advertising: does this guarding under the latch appeal to you?" },
    q7234: { h: "654e7efc9f80", text: "Keeping the confidential matters of a court case carefully even in the machine: would you keep up this guarding of secrets?" },
    q7235: { h: "71dd0b3f9d4c", text: "No bias of caste or gender must creep into the machine's sorting: would you accept this ban on bias?" },
    q7236: { h: "04dac0e1659a", text: "Testing a driverless vehicle on open ground, not in a crowd: will you keep this rule of open ground?" },
    q7237: { h: "a5fa8a14b4b7", text: "A stop line in the swinging range of the arm of an AI robot: would you enjoy this stop line?" },
    q7238: { h: "a2c80ac997e9", text: "Counting the whole ground and clearing it before a launch: does this firmness on counting appeal to you?" },
    q7239: { h: "f7a1b96c361a", text: "Entering the satellite room wearing suit, cap and covers: would you keep up this rule of suit and cap?" },
    q7240: { h: "1d70a3ed6b9d", text: "A body check and practice for every passenger before the trip: would you accept this check and practice?" },
    q7241: { h: "92e618c5d217", text: "Not resting a hand without gloves on frozen metal: will you keep this ban on hands?" },
    q7242: { h: "452543b0c4d5", text: "Out by the air door if the siren of the closed farming room sounds: would you enjoy this respect for the siren?" },
    q7243: { h: "aefad8f9d9ff", text: "Not holding a very cold store without thick gloves: does this ban on holding appeal to you?" },
    q7244: { h: "64b65ddf20dc", text: "A slip in a Mars part is fatal at an endless distance, so a triple check: would you keep up this triple check?" },
    q7245: { h: "80549a11c2d1", text: "A backup copy of the earth image data at a far-off site: would you accept this backup copy?" },
    q7246: { h: "df4fd4575493", text: "Giving a warning at once if the route-finding data goes wrong: will you keep this habit of warning?" },
    q7247: { h: "2429b9ae0098", text: "The matter of a confidential test must not cross the boundary line: would you enjoy this silence at the line?" },
    q7248: { h: "870712e070ef", text: "A battery alarm for the cold room of living samples when the power goes: does this trust in the alarm appeal to you?" },
    q7249: { h: "38c3c37c5147", text: "A proper ladder for climbing the high rows, not a chair: would you keep up this ladder rule?" },
    q7250: { h: "c29f608286c1", text: "Keeping a strict ban on food and water at the experiment bench: would you accept this discipline of the ban?" },
    q7251: { h: "25f236a44b47", text: "Not giving a patient's gene details to anyone without permission: will you keep this watch on permission?" },
    q7252: { h: "509a7c109ec6", text: "Stopping an untested medicine from being given to anyone: would you enjoy this firmness on testing?" },
    q7253: { h: "ef700dbc27c8", text: "The gloves of the germ room in a separate yellow bag: does this habit of the yellow bag appeal to you?" },
    q7254: { h: "da602a46a15b", text: "Never using the tools of one sample on another sample: would you keep up this habit of separation?" },
    q7255: { h: "e97efbb1f901", text: "Hands off and out if the alarm of the bio-tank sounds: would you accept this respect for the alarm?" },
    q7256: { h: "bcf87e93a6d8", text: "Washing hands with soap on leaving the insect rearing room: will you keep this ritual of washing?" },
    q7257: { h: "5641c4e7032d", text: "Rubbing the soles of the shoes at the threshold of the clean room before going in: would you enjoy this rubbing at the threshold?" },
    q7258: { h: "0f5942820490", text: "Working only from the fixed distance near a very hot device: does this rule of distance appeal to you?" },
    q7259: { h: "b9901529b883", text: "The check of the leak alarm of the hydrogen tank every morning: would you keep up this ritual of the alarm?" },
    q7260: { h: "44f1eb3d57ad", text: "Out first as soon as the sharp smell of ammonia comes, then work: would you accept this rule of getting out?" },
    q7261: { h: "8bb91caced50", text: "Entering the battery room only after taking off metal rings and bangles: will you keep this rule of taking them off?" },
    q7262: { h: "e227aaf7aa9c", text: "Never holding a very cold tank without thick gloves: would you enjoy this ban on holding?" },
    q7263: { h: "717cc91376a4", text: "Draining the remaining charge of the storage cell before testing: does this habit of draining appeal to you?" },
    q7264: { h: "115335e63f2c", text: "Dark glasses to protect the eyes from the glare of molten iron: would you keep up these dark glasses?" },
    q7265: { h: "3fc2f28dec43", text: "A filter mask to protect the lungs from cement dust: would you accept this filter rule?" },
    q7266: { h: "addc798a0fee", text: "The check of the leak alarm of the pipe that draws in gas: will you keep this alarm check?" },
